contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params: from address, target contract address, arrays of tos and values
    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        // precondition: contract C.transfer requires _tos.length > 0; require lengths equal to avoid out-of-bounds in P
        require(_tos.length > 0 && _tos.length == v.length);

        // Record c balance before the call
        uint before = address(c).balance;

        // Call transfer and capture whether it reverted
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // The general rule: when provided valid non-empty arrays of equal length, transfer must not revert and must return true,
        // and must not change c's Ether balance (P makes external calls but does not forward Ether).
        assert(reverted == false && ret == true && address(c).balance == before);
    }

    receive() external payable {}
}

contract InvMutTest {
